const normalizeSkill = (value: string) => value.toLowerCase().replace(/[^a-z0-9]/g, "");
const getMatchScore = (profile: StudentProfile, opportunity: Opportunity) => {
  if ((profile.field || "Other") !== opportunity.field) return 0;
  const overlap = opportunity.skills.filter((required) => profile.skills.some((skill) => {
    const studentSkill = normalizeSkill(skill);
    const requiredSkill = normalizeSkill(required);
    return studentSkill === requiredSkill || studentSkill.includes(requiredSkill) || requiredSkill.includes(studentSkill);
  })).length;
  return Math.round((overlap / Math.max(opportunity.skills.length, 1)) * 100);
};
