function Avatar({ name, size = "md" }: { name: string; size?: "sm" | "md" | "lg" }) {
  const initials = name.split(" ").map((part) => part[0]).join("").slice(0, 2);
  const sizeClass = size === "lg" ? "h-14 w-14 text-lg" : size === "sm" ? "h-8 w-8 text-[11px]" : "h-10 w-10 text-xs";
  return <span className={`grid shrink-0 place-items-center rounded-full bg-[#F6C978] font-display font-bold text-[#1B4332] ${sizeClass}`} data-testid={`avatar-${name.toLowerCase().replaceAll(" ", "-")}`}>{initials}</span>;
}
function Button({ children, className = "", variant = "primary", onClick, type = "button", disabled = false, testId }: { children: ReactNode; className?: string; variant?: "primary" | "secondary" | "quiet" | "peach"; onClick?: () => void; type?: "button" | "submit"; disabled?: boolean; testId?: string }) {
  const variants = { primary: "bg-[#1B4332] text-[#FBF9F5] hover:bg-[#285b46]", secondary: "border border-[#d9d4ca] bg-[#FBF9F5] text-[#1B4332] hover:border-[#1B4332]", quiet: "text-[#557066] hover:bg-[#edf0e8] hover:text-[#1B4332]", peach: "bg-[#F3B39D] text-[#1B4332] hover:bg-[#f0a088]" };
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-all duration-200 hover:-translate-y-px disabled:cursor-not-allowed disabled:opacity-50 ${variants[variant]} ${className}`}>{children}</button>;
}
function Input({ label, value, onChange, placeholder, type = "text", testId }: { label?: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string; testId: string }) {
  return <label className="grid gap-1.5 text-sm font-medium text-[#315247]">{label && <span>{label}</span>}<input type={type} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} data-testid={testId} className="h-11 rounded-xl border border-[#d9d4ca] bg-[#fffdfa] px-3.5 text-[#1B4332] outline-none transition focus:border-[#1B4332] focus:ring-2 focus:ring-[#1B4332]/10" /></label>;
}
