function EyeIcon() { return <Eye size={15} />; }
function Feature({ n, icon, title, body }: { n: string; icon: ReactNode; title: string; body: string }) {
  return <div className="rounded-2xl border border-[#e1d9cb] bg-[#FBF9F5] p-6"><div className="flex items-center justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#dfeadf] text-[#1B4332]">{icon}</span><span className="font-mono text-xs text-[#a2998c]">{n}</span></div><h3 className="mt-12 text-xl font-bold tracking-tight">{title}</h3><p className="mt-3 text-sm leading-6 text-[#557066]">{body}</p></div>;
}

function Signup({ showToast, setProfile }: { showToast: (s: string) => void; setProfile: (p: StudentProfile) => void }) {
  const [, setLocation] = useLocation(); const [kind, setKind] = useState<"student" | "company">("student");
  const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState("");
  const submit = (e: FormEvent) => { e.preventDefault(); if (!name || !email || password.length < 6) { setError("Add your name, a valid email, and a 6 character password."); return; } localStorage.setItem("profilio-user", JSON.stringify({ name, email, kind })); if (kind === "student") setProfile({ ...blankProfile, name: name.trim() }); showToast("Account created — welcome to Profilio"); setLocation(kind === "student" ? "/setup/1" : "/company/post"); };
  return <div className="relative min-h-[100dvh] overflow-hidden bg-[#f2eee5]"><div className="pointer-events-none absolute -right-20 top-12 h-72 w-72 rounded-full bg-[#b9d8c8]/70 blur-3xl" /><div className="pointer-events-none absolute -bottom-24 -left-20 h-80 w-80 rounded-full bg-[#cf795f]/25 blur-3xl" /><header className="relative z-10 mx-auto flex max-w-7xl items-center justify-between px-5 py-6 sm:px-8"><Logo /><Link href="/" data-testid="link-back-home" className="text-sm font-semibold text-[#557066]">Back home</Link></header><main className="relative z-10 mx-auto grid max-w-5xl items-center gap-14 px-5 pb-16 pt-10 sm:px-8 md:grid-cols-[.9fr_1fr] md:pt-20"><div><p className="text-sm font-bold uppercase tracking-[.14em] text-[#cf795f]">A profile with a pulse</p><h1 className="mt-4 text-5xl font-extrabold leading-[1.04] tracking-[-.05em]">Start with the<br />good stuff.</h1><p className="mt-5 max-w-sm leading-7 text-[#557066]">Create a home for your work, then let the right opportunities find their way to you.</p><div className="mt-10 hidden items-center gap-3 md:flex"><div className="rounded-2xl bg-[#F6C978] p-4"><Sparkles size={19} /></div><div><p className="text-sm font-bold">Thoughtful by default</p><p className="text-xs text-[#557066]">No noisy feeds. No application black holes.</p></div></div></div><div className="rounded-3xl border border-[#ded5c7] bg-[#FBF9F5] p-6 shadow-xl shadow-[#1B4332]/5 sm:p-9"><div className="flex gap-2 rounded-xl bg-[#f0ece3] p-1"><button onClick={() => setKind("student")} data-testid="button-select-student" className={`flex-1 rounded-lg px-3 py-2.5 text-sm font-bold transition ${kind === "student" ? "bg-[#b9d8c8] text-[#1B4332] shadow-sm" : "text-[#557066]"}`}><UserRound size={15} className="mr-2 inline" />Student</button><button onClick={() => setKind("company")} data-testid="button-select-company" className={`flex-1 rounded-lg px-3 py-2.5 text-sm font-bold transition ${kind === "company" ? "bg-[#b9d8c8] text-[#1B4332] shadow-sm" : "text-[#557066]"}`}><BriefcaseBusiness size={15} className="mr-2 inline" />Company</button></div><div className="mt-7"><h2 className="text-2xl font-extrabold">{kind === "student" ? "Make your work discoverable." : "Meet the people behind the work."}</h2><p className="mt-2 text-sm text-[#557066]">{kind === "student" ? "A few details to get your studio started." : "Reach curious, capable talent directly."}</p></div><form onSubmit={submit} className="mt-7 grid gap-4"><Input label={kind === "student" ? "Your name" : "Company name"} value={name} onChange={setName} placeholder={kind === "student" ? "Aarav Mehta" : "Mosaic Labs"} testId="input-signup-name" /><Input label="Email address" value={email} onChange={setEmail} placeholder="you@example.com" type="email" testId="input-signup-email" /><Input label="Password" value={password} onChange={setPassword} placeholder="At least 6 characters" type="password" testId="input-signup-password" />{error && <p className="text-sm font-medium text-[#b84b42]" data-testid="text-signup-error">{error}</p>}<Button type="submit" testId="button-submit-signup" className="mt-2 w-full">Continue <ArrowRight size={16} /></Button><p className="text-center text-xs text-[#84968e]">Already have an account? <Link href="/signup" data-testid="link-login-signup" className="font-bold text-[#1B4332]">Log In</Link></p></form></div></main></div>;
}

function Setup({ profile, setProfile, showToast }: { profile: StudentProfile; setProfile: (p: StudentProfile) => void; showToast: (s: string) => void }) {
  const { step } = useParams<{ step: string }>(); const current = Number(step) || 1; const [, setLocation] = useLocation();
  const [form, setForm] = useState(profile); const update = (key: keyof StudentProfile, value: string) => setForm((old) => ({ ...old, [key]: value }));
  const next = () => { if (current === 3) { const nextProfile = { ...form, completeness: 100 }; setProfile(nextProfile); showToast("Your profile is live"); setLocation("/dashboard"); } else { setProfile({ ...form, completeness: Math.max(profile.completeness, current === 1 ? 55 : 78) }); setLocation(`/setup/${current + 1}`); } };
  const titles = ["Let’s get to know you.", "Give your profile a point of view.", "Make it easy to find you."];
  return <div className="min-h-[100dvh] bg-[#f2eee5]"><header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-6 sm:px-8"><Logo /><span className="text-xs font-bold uppercase tracking-[.15em] text-[#84968e]">Step {current} of 3</span></header><main className="mx-auto grid max-w-6xl gap-10 px-5 pb-12 pt-8 sm:px-8 md:grid-cols-[1fr_340px] md:pt-14"><div><div className="mb-10 flex gap-2">{[1, 2, 3].map((item) => <span key={item} className={`h-1 flex-1 rounded-full ${item <= current ? "bg-[#1B4332]" : "bg-[#d9d4ca]"}`} />)}</div><p className="text-sm font-bold uppercase tracking-[.14em] text-[#cf795f]">Your studio, your signal</p><h1 className="mt-3 text-4xl font-extrabold tracking-[-.04em] sm:text-5xl">{titles[current - 1]}</h1><p className="mt-3 max-w-lg text-[#557066]">{current === 1 ? "The basics help people place your work in the world." : current === 2 ? "Choose the signals that help the right companies understand your craft." : "Add the links that make your work easy to keep exploring."}</p><div className="mt-9 grid gap-5 sm:grid-cols-2">{current === 1 && <><Input label="Full name" value={form.name} onChange={(v) => update("name", v)} testId="input-setup-name" /><Input label="City" value={form.city} onChange={(v) => update("city", v)} placeholder="Bengaluru" testId="input-setup-city" /><Input label="College name" value={form.college} onChange={(v) => update("college", v)} testId="input-setup-college" /><Input label="Course" value={form.course} onChange={(v) => update("course", v)} testId="input-setup-course" /><Input label="Year" value={form.year} onChange={(v) => update("year", v)} placeholder="3rd year" testId="input-setup-year" /><label className="grid gap-1.5 text-sm font-medium text-[#315247]"><span>Field of interest</span><select value={form.field || "Other"} onChange={(e) => { const field = e.target.value; setForm((old) => ({ ...old, field, skills: fieldSkills[field] ? fieldSkills[field].slice(0, 3) : [] })); }} data-testid="select-setup-field" className="h-11 rounded-xl border border-[#d9d4ca] bg-[#fffdfa] px-3.5 outline-none focus:border-[#1B4332] focus:ring-2 focus:ring-[#1B4332]/10">{fieldOptions.map((field) => <option value={field} key={field}>{field}</option>)}</select></label><label className="sm:col-span-2 grid gap-2 text-sm font-medium text-[#315247]"><span>Short bio</span><textarea value={form.bio} onChange={(e) => update("bio", e.target.value)} rows={5} data-testid="input-setup-bio" className="rounded-xl border border-[#d9d4ca] bg-[#fffdfa] p-3.5 outline-none focus:border-[#1B4332] focus:ring-2 focus:ring-[#1B4332]/10" /></label></>}{current === 2 && <><label className="sm:col-span-2 grid gap-2 text-sm font-medium text-[#315247]"><span>Skills for {form.field || "your field"}</span><div className="flex flex-wrap gap-2 rounded-xl border border-[#d9d4ca] bg-[#fffdfa] p-3">{(fieldSkills[form.field] || fieldSkills.Other).map((skill) => <button type="button" key={skill} onClick={() => setForm((old) => ({ ...old, skills: old.skills.includes(skill) ? old.skills.filter((item) => item !== skill) : [...old.skills, skill] }))} data-testid={`button-skill-${skill.toLowerCase().replaceAll(" ", "-")}`} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${form.skills.includes(skill) ? "bg-[#1B4332] text-white" : "bg-[#e8f0e6] text-[#43705a]"}`}>{skill}</button>)}</div></label><Input label="Add another skill" value={form.skills.join(", ")} onChange={(v) => setForm((old) => ({ ...old, skills: v.split(",").map((s) => s.trim()).filter(Boolean) }))} placeholder={fieldSkills[form.field]?.join(", ") || "Add relevant skills"} testId="input-setup-skills" /></>}{current === 3 && <><Input label="Portfolio link" value={form.portfolioUrl} onChange={(v) => update("portfolioUrl", v)} placeholder="yourname.design" testId="input-setup-portfolio" /><Input label="Behance link" value={form.behanceUrl} onChange={(v) => update("behanceUrl", v)} placeholder="behance.net/yourname" testId="input-setup-behance" /></>}</div><div className="mt-10 flex items-center gap-3"><Button variant="secondary" onClick={() => current > 1 ? setLocation(`/setup/${current - 1}`) : setLocation("/signup")} testId="button-setup-back"><ChevronLeft size={16} /> Back</Button><Button onClick={next} testId="button-setup-next">{current === 3 ? "Finish Setup" : "Next Step"} <ArrowRight size={16} /></Button></div></div><div className="hidden md:block"><ProfilePreview profile={form} /></div></main></div>;
}
function ProfilePreview({ profile }: { profile: StudentProfile }) {
  return <div className="sticky top-8 rounded-3xl border border-[#ded5c7] bg-[#FBF9F5] p-5 shadow-lg shadow-[#1B4332]/5"><div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-[.15em] text-[#84968e]"><span>Live preview</span><span className="text-[#cf795f]">Public</span></div><div className="mt-7 flex items-center gap-3"><Avatar name={profile.name || "Your Name"} size="lg" /><div><p className="font-display text-lg font-bold text-[#1B4332]">{profile.name || "Your Name"}</p><p className="text-xs text-[#557066]">{profile.city || "Your city"} · {profile.course || "Your discipline"}</p></div></div><p className="mt-6 text-sm leading-6 text-[#557066]">{profile.bio || "Your introduction will appear here. Make it specific and a little human."}</p><div className="mt-6 flex flex-wrap gap-1.5">{(profile.skills.length ? profile.skills : ["Your skills"]).map((skill) => <span key={skill} className="rounded-full bg-[#e8f0e6] px-2.5 py-1 text-[11px] font-semibold text-[#43705a]">{skill}</span>)}</div><div className="mt-8 border-t border-[#ebe5da] pt-4 text-xs text-[#84968e]">Profilio profile · {profile.completeness}% complete</div></div>;
}

function PageTitle({ eyebrow, title, body, action }: { eyebrow?: string; title: string; body?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-[#cf795f]">{eyebrow}</p>}<h1 className="text-3xl font-extrabold tracking-[-.04em] text-[#1B4332] sm:text-4xl">{title}</h1>{body && <p className="mt-2 max-w-xl text-sm leading-6 text-[#557066]">{body}</p>}</div>{action}</div>;
}
function Dashboard({ profile, projects, notifications, showToast }: { profile: StudentProfile; projects: Project[]; notifications: Notification[]; showToast: (s: string) => void }) {
  const [, setLocation] = useLocation(); const recent = notifications.slice(0, 3);
  return <Shell profile={profile} unread={notifications.filter((n) => n.unread).length}><PageTitle eyebrow="Your studio" title={`Hi ${profile.name.split(" ")[0]}, you are being noticed.`} body="Here’s what’s happening around your work this week." action={<Button onClick={() => setLocation("/portfolio/new")} testId="button-dashboard-add-project"><Plus size={17} /> Add project</Button>} /><div className="grid gap-4 lg:grid-cols-[1.4fr_.8fr]"><section className="rounded-3xl bg-[#1B4332] p-6 text-[#FBF9F5] sm:p-8"><div className="flex items-start justify-between"><div><p className="text-sm text-[#b9d1c1]">Portfolio reach</p><p className="mt-2 text-5xl font-extrabold tracking-[-.06em]">544</p><p className="mt-2 text-xs text-[#b9d1c1]"><span className="font-bold text-[#F6C978]">+18.4%</span> compared with last week</p></div><div className="rounded-xl bg-[#285b46] p-3 text-[#F6C978]"><TrendingUp size={20} /></div></div><div className="mt-8 flex h-24 items-end gap-2">{[26, 34, 28, 48, 42, 67, 57, 82, 72, 90, 78, 100, 88, 95].map((height, i) => <div key={i} className="flex-1 rounded-t-md bg-[#F6C978]/80 transition hover:bg-[#F6C978]" style={{ height: `${height}%` }} />)}</div><div className="mt-2 flex justify-between text-[10px] text-[#90b4a0]"><span>May 06</span><span>May 12</span><span>Today</span></div></section><section className="studio-card studio-shadow p-6"><div className="flex items-center justify-between"><h2 className="font-display text-lg font-bold">Profile strength</h2><span className="text-2xl font-extrabold text-[#cf795f]">{profile.completeness}%</span></div><div className="mt-5 h-2 rounded-full bg-[#e4e9df]"><div className="h-full rounded-full bg-[#cf795f]" style={{ width: `${profile.completeness}%` }} /></div><p className="mt-5 text-sm leading-6 text-[#557066]">One more project could help companies see the full shape of your thinking.</p><Button variant="secondary" className="mt-5 w-full" onClick={() => setLocation("/portfolio/new")} testId="button-complete-profile">Add a project <ArrowRight size={15} /></Button></section></div><div className="mt-7 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="studio-card p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.13em] text-[#84968e]">Your work</p><h2 className="mt-1 font-display text-xl font-bold">Portfolio highlights</h2></div><Link href="/portfolio" data-testid="link-view-portfolio" className="text-sm font-bold text-[#43705a]">View all <ArrowRight size={14} className="ml-1 inline" /></Link></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{projects.slice(0, 2).map((project) => <ProjectMini key={project.id} project={project} />)}</div></section><section className="studio-card p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.13em] text-[#84968e]">Signals</p><h2 className="mt-1 font-display text-xl font-bold">Recent activity</h2></div><Link href="/activity" data-testid="link-view-activity" className="text-sm font-bold text-[#43705a]">See all</Link></div><div className="mt-4 grid gap-1">{recent.map((item) => <Link href="/activity" key={item.id} data-testid={`row-dashboard-notification-${item.id}`} className="flex gap-3 rounded-xl p-2.5 transition hover:bg-[#f3f0e9]"><span className={`mt-1 grid h-7 w-7 shrink-0 place-items-center rounded-lg ${item.type === "message" ? "bg-[#f7ddd3]" : "bg-[#e8f0e6]"}`}>{item.type === "message" ? <MessageCircle size={14} /> : <EyeIcon />}</span><div className="min-w-0"><p className="truncate text-xs font-semibold">{item.title}</p><p className="mt-0.5 text-[11px] text-[#84968e]">{item.timestamp}</p></div></Link>)}</div></section></div><div className="mt-7 rounded-3xl border border-[#dbe5d7] bg-[#e8f0e6] p-6 sm:flex sm:items-center sm:justify-between"><div className="flex gap-4"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-[#F6C978] text-[#1B4332]"><Sparkles size={20} /></div><div><h2 className="font-display text-lg font-bold">Your profile is a living thing.</h2><p className="mt-1 text-sm text-[#557066]">Refresh a project or add a note about what you’re exploring lately.</p></div></div><Button variant="quiet" className="mt-4 sm:mt-0" onClick={() => showToast("Small updates make a strong signal")} testId="button-dashboard-tip">Got it <Check size={15} /></Button></div></Shell>;
}
function ProjectMini({ project }: { project: Project }) {
  return <Link href={`/portfolio`} data-testid={`card-dashboard-project-${project.id}`} className="group overflow-hidden rounded-2xl border border-[#e6e1d8] bg-[#fffdfa]"><ProjectArt variant={project.thumbnail} small /><div className="p-3.5"><div className="flex items-center justify-between"><h3 className="text-sm font-bold">{project.title}</h3><span className="text-[10px] text-[#84968e]">{project.views} views</span></div><p className="mt-1 text-xs text-[#84968e]">{project.category}</p></div></Link>;
}
function ProjectArt({ variant, small = false }: { variant: string; small?: boolean }) {
  const styles: Record<string, string> = { mint: "bg-[#b9d8c8]", peach: "bg-[#f3b39d]", yellow: "bg-[#f6c978]", lavender: "bg-[#c7c9df]" };
  return <div className={`relative overflow-hidden ${small ? "h-28" : "h-48"} ${styles[variant] || styles.mint}`}><div className="absolute -right-8 -top-10 h-32 w-32 rounded-full border-[18px] border-[#1B4332]/15" /><div className="absolute bottom-[-35px] left-[-15px] h-28 w-28 rotate-12 rounded-[2rem] border-8 border-[#FBF9F5]/40" /><span className="absolute bottom-3 left-3 rounded-full bg-[#FBF9F5]/75 px-2 py-1 text-[9px] font-bold uppercase tracking-wider text-[#1B4332]">process / {small ? "01" : "selected"}</span></div>;
}

function Portfolio({ profile, projects, setProjects, showToast }: { profile: StudentProfile; projects: Project[]; setProjects: (p: Project[]) => void; showToast: (s: string) => void }) {
  const [, setLocation] = useLocation(); const [filter, setFilter] = useState("All work");
  const categories = ["All work", ...Array.from(new Set(projects.map((p) => p.category)))]; const visible = filter === "All work" ? projects : projects.filter((p) => p.category === filter);
  const feature = projects.find((p) => p.featured);
  const remove = (id: string) => { if (window.confirm("Remove this project from your portfolio?")) { setProjects(projects.filter((p) => p.id !== id)); showToast("Project removed"); } };
  return <Shell profile={profile} unread={0}><PageTitle eyebrow="Your body of work" title="Portfolio" body="A considered collection of the things you’ve made, tested, and learned." action={<Button onClick={() => setLocation("/portfolio/new")} testId="button-add-project"><Plus size={17} /> Add project</Button>} />{feature && <div className="mb-8 grid overflow-hidden rounded-3xl bg-[#1B4332] text-[#FBF9F5] md:grid-cols-[1.1fr_.9fr]"><ProjectArt variant={feature.thumbnail} /><div className="flex flex-col justify-between p-6 sm:p-8"><div><div className="flex items-center justify-between"><span className="rounded-full bg-[#F6C978] px-2.5 py-1 text-[10px] font-bold tracking-wider text-[#1B4332]">FEATURED PROJECT</span><button onClick={() => showToast("Featured project options")} data-testid="button-featured-options"><MoreHorizontal size={19} className="text-[#b9d1c1]" /></button></div><h2 className="mt-8 max-w-md text-3xl font-extrabold tracking-[-.04em]">{feature.title}</h2><p className="mt-3 max-w-md text-sm leading-6 text-[#b9d1c1]">{feature.description}</p></div><div className="mt-8 flex items-center justify-between"><div className="flex gap-1.5">{feature.tools.map((tool) => <span className="rounded-full bg-[#285b46] px-2.5 py-1 text-[10px] text-[#c7dacc]" key={tool}>{tool}</span>)}</div><button onClick={() => setLocation(`/portfolio/new?id=${feature.id}`)} data-testid="button-edit-featured" className="text-sm font-bold text-[#F6C978]">Edit <ArrowRight size={14} className="ml-1 inline" /></button></div></div></div>}<div className="mb-5 flex items-center gap-2 overflow-auto pb-1">{categories.map((cat) => <button key={cat} onClick={() => setFilter(cat)} data-testid={`button-portfolio-filter-${cat.toLowerCase().replaceAll(" ", "-")}`} className={`whitespace-nowrap rounded-full px-3.5 py-2 text-xs font-bold transition ${filter === cat ? "bg-[#1B4332] text-white" : "bg-[#e8eee7] text-[#557066] hover:bg-[#dce8db]"}`}>{cat}</button>)}</div><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{visible.map((project) => <article key={project.id} className="studio-card group overflow-hidden transition hover:-translate-y-1 hover:shadow-lg"><ProjectArt variant={project.thumbnail} /><div className="p-5"><div className="flex items-start justify-between gap-3"><div><h3 className="font-display text-lg font-bold">{project.title}</h3><p className="mt-1 text-xs font-medium text-[#84968e]">{project.category}</p></div><button onClick={() => remove(project.id)} data-testid={`button-delete-project-${project.id}`} className="rounded-lg p-1.5 text-[#84968e] opacity-0 transition group-hover:opacity-100 hover:bg-[#f8ddd6] hover:text-[#b84b42]"><Trash2 size={15} /></button></div><p className="mt-4 text-sm leading-6 text-[#557066]">{project.description}</p><div className="mt-5 flex items-center justify-between border-t border-[#eee9e0] pt-4 text-xs text-[#84968e]"><span>{project.views} views</span><span className="flex items-center gap-1"><Globe2 size={13} /> {project.visibility}</span></div></div></article>)}</div>{visible.length === 0 && <div className="rounded-3xl border border-dashed border-[#cfc7b9] py-20 text-center"><FolderOpen className="mx-auto text-[#84968e]" size={28} /><p className="mt-3 font-display font-bold">No projects in this filter yet.</p></div>}</Shell>;
}

function NewProject({ profile, projects, setProjects, showToast }: { profile: StudentProfile; projects: Project[]; setProjects: (p: Project[]) => void; showToast: (s: string) => void }) {
  const [, setLocation] = useLocation(); const params = new URLSearchParams(window.location.search); const editId = params.get("id"); const existing = projects.find((p) => p.id === editId);
  const [title, setTitle] = useState(existing?.title || ""); const [description, setDescription] = useState(existing?.description || ""); const [category, setCategory] = useState(existing?.category || "Product design"); const [tools, setTools] = useState(existing?.tools.join(", ") || ""); const [link, setLink] = useState(existing?.externalLink || ""); const [thumb, setThumb] = useState(existing?.thumbnail || "mint"); const [fileName, setFileName] = useState("");
  const submit = (e: FormEvent) => { e.preventDefault(); if (!title.trim() || !description.trim()) { showToast("Add a title and a short description first"); return; } const project: Project = { id: existing?.id || `p${Date.now()}`, title, description, tools: tools.split(",").map((x) => x.trim()).filter(Boolean), category, externalLink: link, visibility: "Public", allowComments: true, thumbnail: thumb, views: existing?.views || 0, featured: existing?.featured || false }; setProjects(existing ? projects.map((p) => p.id === existing.id ? project : p) : [project, ...projects]); showToast(existing ? "Project updated" : "Project added to your portfolio"); setLocation("/portfolio"); };
  return <Shell profile={profile} unread={0}><div className="mb-8 flex items-center gap-3 text-sm text-[#84968e]"><button onClick={() => setLocation("/portfolio")} data-testid="button-back-portfolio" className="hover:text-[#1B4332]"><ChevronLeft size={17} /></button><span>Portfolio</span><span>/</span><span className="font-semibold text-[#1B4332]">{existing ? "Edit project" : "New project"}</span></div><div className="mx-auto max-w-4xl"><PageTitle eyebrow={existing ? "Keep it fresh" : "Add to your story"} title={existing ? "Edit project" : "Share something you made."} body="Give people enough context to understand what you saw, tried, and changed." /><form onSubmit={submit} className="grid gap-6 md:grid-cols-[1.1fr_.9fr]"><div className="studio-card p-6 sm:p-8"><div className="grid gap-5"><Input label="Project title" value={title} onChange={setTitle} placeholder="A gentler way to commute" testId="input-project-title" /><label className="grid gap-1.5 text-sm font-medium text-[#315247]"><span>What was this about?</span><textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="A few lines about the question, the process, or the outcome." rows={6} data-testid="input-project-description" className="rounded-xl border border-[#d9d4ca] bg-[#fffdfa] p-3.5 outline-none focus:border-[#1B4332] focus:ring-2 focus:ring-[#1B4332]/10" /></label><Input label="Tools and skills" value={tools} onChange={setTools} placeholder="Figma, research, prototyping" testId="input-project-tools" /><Input label="External link (optional)" value={link} onChange={setLink} placeholder="https://" testId="input-project-link" /><label className="grid gap-1.5 text-sm font-medium text-[#315247]"><span>Category</span><select value={category} onChange={(e) => setCategory(e.target.value)} data-testid="select-project-category" className="h-11 rounded-xl border border-[#d9d4ca] bg-[#fffdfa] px-3.5 outline-none"><option>Product design</option><option>Visual design</option><option>Research</option><option>Writing</option><option>Engineering</option></select></label></div></div><div className="grid content-start gap-5"><div className="studio-card overflow-hidden"><ProjectArt variant={thumb} /><div className="p-5"><p className="text-sm font-bold">Cover preview</p><p className="mt-1 text-xs leading-5 text-[#84968e]">Choose a visual mood for this project.</p><div className="mt-4 flex gap-2">{["mint", "peach", "yellow", "lavender"].map((item) => <button type="button" key={item} onClick={() => setThumb(item)} data-testid={`button-project-color-${item}`} className={`h-8 w-8 rounded-full bg-${item} ${item === "mint" ? "bg-[#b9d8c8]" : item === "peach" ? "bg-[#f3b39d]" : item === "yellow" ? "bg-[#f6c978]" : "bg-[#c7c9df]"} ${thumb === item ? "ring-2 ring-[#1B4332] ring-offset-2" : ""}`} aria-label={`Use ${item} cover`} />)}</div></div></div><label className="studio-card flex cursor-pointer items-center gap-3 border-dashed p-5 transition hover:bg-[#f6f3ed]"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e8f0e6] text-[#1B4332]"><Upload size={17} /></span><span><span className="block text-sm font-bold">{fileName || "Upload a cover file"}</span><span className="mt-1 block text-xs text-[#84968e]">PNG, JPG, or PDF · max 10MB</span></span><input type="file" accept="image/*,.pdf" onChange={(e) => setFileName(e.target.files?.[0]?.name || "")} data-testid="input-project-file" className="sr-only" /></label><div className="flex gap-3"><Button variant="secondary" onClick={() => setLocation("/portfolio")} testId="button-cancel-project">Cancel</Button><Button type="submit" className="flex-1" testId="button-save-project">{existing ? "Save changes" : "Publish project"} <ArrowRight size={15} /></Button></div></div></form></div></Shell>;
}

function CompanyPost({ setCompanyOpportunities, showToast }: { setCompanyOpportunities: (items: Opportunity[]) => void; showToast: (s: string) => void }) {
  const [, setLocation] = useLocation();
  const [role, setRole] = useState(""); const [company, setCompany] = useState(""); const [location, setPostingLocation] = useState(""); const [stipend, setStipend] = useState(""); const [description, setDescription] = useState("");
  const [field, setField] = useState("Web Development"); const [skills, setSkills] = useState<string[]>(fieldSkills["Web Development"].slice(0, 3));
  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (!role.trim() || !company.trim() || !location.trim() || !description.trim() || skills.length === 0) { showToast("Add the role, company, field, and at least one required skill"); return; }
    const item: Opportunity = { id: `company-${Date.now()}`, role: role.trim(), company: company.trim(), location: location.trim(), stipend: stipend.trim() || "Stipend shared during interview", matchScore: 0, field, skills, season: "New opening", description: description.trim() };
    setCompanyOpportunities([item]); showToast("Internship published for the right students"); setLocation("/opportunities");
  };
  const availableSkills = fieldSkills[field] || fieldSkills.Other;
  return <div className="min-h-[100dvh] bg-[#f2eee5]"><header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-6 sm:px-8"><Logo /><Link href="/" data-testid="link-company-home" className="text-sm font-semibold text-[#557066]">Back home</Link></header><main className="mx-auto max-w-5xl px-5 pb-16 pt-8 sm:px-8 md:pt-14"><PageTitle eyebrow="For companies" title="Post an internship that finds its people." body="Choose a field and the skills you need. Profilio will show the opening to relevant students and calculate their fit from their profiles." /><form onSubmit={submit} className="grid gap-6 md:grid-cols-[1fr_.8fr]"><div className="studio-card grid gap-5 p-6 sm:p-8"><Input label="Role title" value={role} onChange={setRole} placeholder="Frontend Development Intern" testId="input-company-role" /><Input label="Company name" value={company} onChange={setCompany} placeholder="Northstar" testId="input-company-name" /><Input label="Location" value={location} onChange={setPostingLocation} placeholder="Remote · India" testId="input-company-location" /><Input label="Stipend" value={stipend} onChange={setStipend} placeholder="₹35,000 / month" testId="input-company-stipend" /><label className="grid gap-1.5 text-sm font-medium text-[#315247]"><span>Field category</span><select value={field} onChange={(e) => { const nextField = e.target.value; setField(nextField); setSkills((fieldSkills[nextField] || fieldSkills.Other).slice(0, 3)); }} data-testid="select-company-field" className="h-11 rounded-xl border border-[#d9d4ca] bg-[#fffdfa] px-3.5 outline-none focus:border-[#1B4332]">{fieldOptions.map((item) => <option key={item} value={item}>{item}</option>)}</select></label><label className="grid gap-1.5 text-sm font-medium text-[#315247]"><span>Role description</span><textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={6} placeholder="What will this intern learn, own, and contribute?" data-testid="input-company-description" className="rounded-xl border border-[#d9d4ca] bg-[#fffdfa] p-3.5 outline-none focus:border-[#1B4332] focus:ring-2 focus:ring-[#1B4332]/10" /></label><Button type="submit" testId="button-publish-internship">Publish internship <ArrowRight size={16} /></Button></div><aside className="studio-card h-fit p-6 sm:p-8"><p className="text-xs font-bold uppercase tracking-[.14em] text-[#cf795f]">Required skills</p><h2 className="mt-2 font-display text-xl font-bold">Tag the signals you need.</h2><p className="mt-2 text-sm leading-6 text-[#557066]">These skills power field-aware matching for students.</p><div className="mt-5 flex flex-wrap gap-2">{availableSkills.map((skill) => <button type="button" key={skill} onClick={() => setSkills((current) => current.includes(skill) ? current.filter((item) => item !== skill) : [...current, skill])} data-testid={`button-company-skill-${skill.toLowerCase().replaceAll(" ", "-")}`} className={`rounded-full px-3 py-2 text-xs font-semibold ${skills.includes(skill) ? "bg-[#1B4332] text-white" : "bg-[#e8f0e6] text-[#43705a]"}`}>{skill}</button>)}</div><div className="mt-8 rounded-2xl bg-[#e8f0e6] p-4 text-sm text-[#315247]"><strong>{field}</strong><p className="mt-1 text-xs leading-5 text-[#557066]">Only students who selected this field will see the internship.</p></div></aside></form></main></div>;
}

function Opportunities({ profile, opportunities, bookmarks, setBookmarks, showToast }: { profile: StudentProfile; opportunities: Opportunity[]; bookmarks: string[]; setBookmarks: (b: string[]) => void; showToast: (s: string) => void }) {
  const [search, setSearch] = useState(""); const [season, setSeason] = useState("All seasons"); const [filterOpen, setFilterOpen] = useState(false);
  const field = profile.field || "Other";
  const filtered = opportunities.filter((o) => o.field === field && (o.role + o.company + o.skills.join(" ")).toLowerCase().includes(search.toLowerCase()) && (season === "All seasons" || o.season === season));
  const toggle = (id: string) => { const added = !bookmarks.includes(id); setBookmarks(added ? [...bookmarks, id] : bookmarks.filter((b) => b !== id)); showToast(added ? "Opportunity saved" : "Removed from saved"); };
  return <Shell profile={profile} unread={2}><PageTitle eyebrow={`Curated for ${field}`} title="Opportunities" body={`Roles tagged for ${field}, with match scores based on your selected skills.`} action={<span className="flex items-center gap-2 text-sm font-semibold text-[#557066]"><Bookmark size={16} /> {bookmarks.length} saved</span>} /><div className="mb-7 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search size={17} className="absolute left-3.5 top-3.5 text-[#84968e]" /><input value={search} onChange={(e) => setSearch(e.target.value)} data-testid="input-opportunity-search" placeholder="Search roles, skills, or companies" className="h-11 w-full rounded-xl border border-[#d9d4ca] bg-[#fffdfa] pl-10 pr-4 text-sm outline-none focus:border-[#1B4332] focus:ring-2 focus:ring-[#1B4332]/10" /></div><button onClick={() => setFilterOpen(!filterOpen)} data-testid="button-toggle-filters" className={`flex h-11 items-center justify-center gap-2 rounded-xl border px-4 text-sm font-semibold ${filterOpen ? "border-[#1B4332] bg-[#e8f0e6]" : "border-[#d9d4ca] bg-[#fffdfa]"}`}><Filter size={16} /> Filters</button></div>{filterOpen && <div className="mb-6 flex flex-wrap items-center gap-3 rounded-2xl border border-[#dbe5d7] bg-[#e8f0e6] p-4"><span className="text-xs font-bold uppercase tracking-wider text-[#557066]">Season</span>{["All seasons", "Summer 2025", "Monsoon 2025", "New opening"].map((item) => <button key={item} onClick={() => setSeason(item)} data-testid={`button-filter-season-${item.replaceAll(" ", "-").toLowerCase()}`} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${season === item ? "bg-[#1B4332] text-white" : "bg-white text-[#557066]"}`}>{item}</button>)}</div>}<div className="mb-5 flex items-center justify-between text-sm text-[#84968e]"><span>{filtered.length} {field} opportunities worth a closer look</span><button onClick={() => setSearch("")} data-testid="button-clear-opportunity-search" className="flex items-center gap-1 font-semibold text-[#43705a]"><ListFilter size={14} /> Curated for you</button></div>{filtered.length ? <div className="grid gap-5 md:grid-cols-2">{filtered.map((op) => <OpportunityCard key={op.id} opportunity={{ ...op, matchScore: getMatchScore(profile, op) }} bookmarked={bookmarks.includes(op.id)} onToggle={() => toggle(op.id)} />)}</div> : <div className="studio-card border-dashed py-20 text-center"><Search className="mx-auto text-[#84968e]" /><h3 className="mt-4 font-display font-bold">No {field} internships yet.</h3><p className="mt-2 text-sm text-[#84968e]">Try another search, or check back as companies add new openings.</p></div>}</Shell>;
}
function OpportunityCard({ opportunity: op, bookmarked, onToggle }: { opportunity: Opportunity; bookmarked: boolean; onToggle: () => void }) {
  return <article className="studio-card group relative p-5 transition hover:-translate-y-1 hover:shadow-lg sm:p-6"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-[#1B4332] text-xs font-bold text-[#F6C978]">{op.company.split(" ").map((x) => x[0]).join("").slice(0, 2)}</span><div><h2 className="font-display text-lg font-bold">{op.role}</h2><p className="mt-0.5 text-xs text-[#557066]">{op.company}</p></div></div><button onClick={onToggle} data-testid={`button-bookmark-opportunity-${op.id}`} className={`rounded-lg p-2 transition ${bookmarked ? "bg-[#f7ddd3] text-[#b84b42]" : "text-[#84968e] hover:bg-[#f0ece3]"}`}><Bookmark size={17} fill={bookmarked ? "currentColor" : "none"} /></button></div><div className="mt-6 flex items-center justify-between rounded-xl bg-[#e8f0e6] px-3 py-2.5"><span className="flex items-center gap-1.5 text-xs font-semibold text-[#43705a]"><Sparkles size={14} /> {op.matchScore}% match</span><span className="text-[11px] font-medium text-[#557066]">{op.season}</span></div><div className="mt-5 grid gap-2 text-xs text-[#557066]"><span className="flex items-center gap-2"><MapPin size={14} />{op.location}</span><span className="flex items-center gap-2"><BriefcaseBusiness size={14} />{op.stipend}</span></div><div className="mt-5 flex flex-wrap gap-1.5">{op.skills.map((skill) => <span key={skill} className="rounded-full border border-[#e1e6de] px-2.5 py-1 text-[10px] font-medium text-[#557066]">{skill}</span>)}</div><Link href={`/opportunities/${op.id}`} data-testid={`link-opportunity-${op.id}`} className="mt-6 flex items-center justify-between border-t border-[#eee9e0] pt-4 text-sm font-bold text-[#1B4332]">View opportunity <ArrowRight size={16} className="transition group-hover:translate-x-1" /></Link></article>;
}

function OpportunityDetail({ profile, opportunities, bookmarks, setBookmarks, showToast }: { profile: StudentProfile; opportunities: Opportunity[]; bookmarks: string[]; setBookmarks: (b: string[]) => void; showToast: (s: string) => void }) {
  const { id } = useParams<{ id: string }>(); const raw = opportunities.find((item) => item.id === id) || opportunities[0]; const op = { ...raw, matchScore: getMatchScore(profile, raw) }; const [, setLocation] = useLocation(); const saved = bookmarks.includes(op.id);
  return <Shell profile={profile} unread={2}><button onClick={() => setLocation("/opportunities")} data-testid="button-back-opportunities" className="mb-7 flex items-center gap-2 text-sm font-semibold text-[#557066] hover:text-[#1B4332]"><ChevronLeft size={17} /> All opportunities</button><div className="grid gap-8 lg:grid-cols-[1fr_340px]"><div><div className="flex items-center gap-4"><span className="grid h-16 w-16 place-items-center rounded-3xl bg-[#1B4332] text-lg font-bold text-[#F6C978]">{op.company.split(" ").map((x) => x[0]).join("").slice(0, 2)}</span><div><p className="text-sm font-semibold text-[#557066]">{op.company} · {op.field}</p><h1 className="mt-1 text-3xl font-extrabold tracking-[-.04em] sm:text-4xl">{op.role}</h1></div></div><div className="mt-10 flex flex-wrap gap-2">{op.skills.map((skill) => <span key={skill} className="rounded-full bg-[#e8f0e6] px-3 py-1.5 text-xs font-semibold text-[#43705a]">{skill}</span>)}</div><div className="mt-10 border-t border-[#e1dcd2] pt-8"><h2 className="font-display text-xl font-bold">The role</h2><p className="mt-4 max-w-2xl text-base leading-8 text-[#557066]">{op.description}</p><p className="mt-4 max-w-2xl text-base leading-8 text-[#557066]">You’ll work alongside a small, kind team that values clear questions, generous critique, and shipping work that earns its place in someone’s day.</p></div><div className="mt-9 border-t border-[#e1dcd2] pt-8"><h2 className="font-display text-xl font-bold">What you’ll bring</h2><div className="mt-4 grid gap-3 sm:grid-cols-2"><Checklist text={`Relevant ${op.field} experience`} /><Checklist text="Comfort with open-ended problems" /><Checklist text="A portfolio that shows your process" /><Checklist text="The courage to ask better questions" /></div></div></div><aside className="h-fit rounded-3xl bg-[#1B4332] p-6 text-[#FBF9F5] lg:sticky lg:top-8"><p className="text-xs font-bold uppercase tracking-[.14em] text-[#b9d1c1]">Your signal</p><div className="mt-4 flex items-end gap-2"><span className="text-6xl font-extrabold tracking-[-.07em] text-[#F6C978]">{op.matchScore}</span><span className="mb-2 text-sm text-[#b9d1c1]">/ 100 match</span></div><p className="mt-3 text-sm leading-6 text-[#c5d8cb]">Calculated from your {profile.field || "selected"} skills and this role’s requirements.</p><div className="my-6 border-t border-[#39634e] pt-5 text-sm"><div className="flex justify-between py-2"><span className="text-[#b9d1c1]">Field</span><span>{op.field}</span></div><div className="flex justify-between py-2"><span className="text-[#b9d1c1]">Location</span><span>{op.location}</span></div><div className="flex justify-between py-2"><span className="text-[#b9d1c1]">Compensation</span><span>{op.stipend}</span></div><div className="flex justify-between py-2"><span className="text-[#b9d1c1]">Season</span><span>{op.season}</span></div></div><Button className="w-full bg-[#F6C978] !text-[#1B4332] hover:bg-[#f8d58f]" onClick={() => showToast("Your interest has been shared with the team")} testId="button-express-interest">Express interest <ArrowRight size={15} /></Button><button onClick={() => { setBookmarks(saved ? bookmarks.filter((b) => b !== op.id) : [...bookmarks, op.id]); showToast(saved ? "Opportunity unsaved" : "Opportunity saved"); }} data-testid="button-detail-bookmark" className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl py-2.5 text-sm font-semibold text-[#c5d8cb] hover:bg-[#285b46]">{saved ? <Check size={15} /> : <Bookmark size={15} />} {saved ? "Saved to your list" : "Save for later"}</button></aside></div></Shell>;
}
function Checklist({ text }: { text: string }) { return <div className="flex items-center gap-2 text-sm text-[#557066]"><span className="grid h-5 w-5 place-items-center rounded-full bg-[#e8f0e6] text-[#43705a]"><Check size={12} /></span>{text}</div>; }

function Messages({ profile, conversations, setConversations, showToast }: { profile: StudentProfile; conversations: Conversation[]; setConversations: (c: Conversation[]) => void; showToast: (s: string) => void }) {
  const [selected, setSelected] = useState(conversations[0]?.id || ""); const [draft, setDraft] = useState(""); const convo = conversations.find((c) => c.id === selected) || conversations[0];
  const send = (e: FormEvent) => { e.preventDefault(); if (!draft.trim() || !convo) return; const updated = conversations.map((c) => c.id === convo.id ? { ...c, messages: [...c.messages, { id: `m${Date.now()}`, text: draft.trim(), from: "me" as const, time: "Now" }] } : c); setConversations(updated); setDraft(""); showToast("Message sent"); };
  return <Shell profile={profile} unread={2}><PageTitle eyebrow="The human bit" title="Messages" body="Conversations with people who have already spent time with your work." /><div className="grid min-h-[560px] overflow-hidden rounded-3xl border border-[#ded9cf] bg-[#fffdfa] md:grid-cols-[250px_1fr]"><aside className="border-b border-[#e6e1d8] md:border-b-0 md:border-r"><div className="flex items-center justify-between border-b border-[#e6e1d8] p-4"><span className="text-xs font-bold uppercase tracking-[.14em] text-[#84968e]">Inbox</span><button onClick={() => showToast("All caught up")} data-testid="button-inbox-options"><MoreHorizontal size={17} className="text-[#84968e]" /></button></div>{conversations.map((item) => <button key={item.id} onClick={() => setSelected(item.id)} data-testid={`button-conversation-${item.id}`} className={`flex w-full gap-3 border-b border-[#eee9e0] p-4 text-left transition ${selected === item.id ? "bg-[#e8f0e6]" : "hover:bg-[#f7f4ef]"}`}><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[#F6C978] text-[10px] font-bold text-[#1B4332]">{item.company.split(" ").map((x) => x[0]).join("").slice(0, 2)}</span><span className="min-w-0"><span className="flex items-center justify-between gap-2"><span className="truncate text-sm font-bold">{item.company}</span>{item.online && <span className="h-2 w-2 rounded-full bg-[#5ba477]" />}</span><span className="mt-1 block truncate text-xs text-[#84968e]">{item.messages[item.messages.length - 1]?.text}</span></span></button>)}</aside>{convo ? <section className="flex min-h-[500px] flex-col"><header className="flex items-center justify-between border-b border-[#e6e1d8] p-4 sm:px-6"><div className="flex items-center gap-3"><Avatar name={convo.recruiter} size="sm" /><div><h2 className="text-sm font-bold">{convo.recruiter}</h2><p className="text-xs text-[#84968e]">{convo.company} · {convo.online ? "Online now" : "Last active yesterday"}</p></div></div><button onClick={() => showToast("Conversation options")} data-testid="button-conversation-options"><MoreHorizontal size={18} className="text-[#84968e]" /></button></header><div className="flex-1 space-y-4 overflow-y-auto p-5 sm:p-7">{convo.messages.map((message) => <div key={message.id} className={`flex ${message.from === "me" ? "justify-end" : "justify-start"}`}><div className={`max-w-[82%] rounded-2xl px-4 py-3 text-sm leading-6 ${message.from === "me" ? "rounded-br-sm bg-[#1B4332] text-[#FBF9F5]" : "rounded-bl-sm bg-[#f0ece3] text-[#315247]"}`}><p>{message.text}</p><p className={`mt-1 text-[10px] ${message.from === "me" ? "text-[#b9d1c1]" : "text-[#84968e]"}`}>{message.time}</p></div></div>)}</div><form onSubmit={send} className="flex gap-2 border-t border-[#e6e1d8] p-4"><input value={draft} onChange={(e) => setDraft(e.target.value)} placeholder="Write a thoughtful reply..." data-testid="input-message-draft" className="min-w-0 flex-1 rounded-xl border border-[#d9d4ca] bg-[#FBF9F5] px-3.5 text-sm outline-none focus:border-[#1B4332]" /><Button type="submit" className="px-3" testId="button-send-message"><Send size={16} /></Button></form></section> : <div className="grid place-items-center p-10 text-center"><Inbox className="text-[#84968e]" /><p className="mt-3 font-semibold">Your inbox is quiet.</p></div>}</div></Shell>;
}

function Activity({ profile, notifications, setNotifications }: { profile: StudentProfile; notifications: Notification[]; setNotifications: (n: Notification[]) => void }) {
  const [filter, setFilter] = useState<"all" | "unread">("all"); const visible = filter === "unread" ? notifications.filter((n) => n.unread) : notifications; const markAll = () => setNotifications(notifications.map((n) => ({ ...n, unread: false })));
  return <Shell profile={profile} unread={notifications.filter((n) => n.unread).length}><PageTitle eyebrow="Signals around your work" title="Activity" body="A quiet record of the people and opportunities moving closer." action={<Button variant="secondary" onClick={markAll} testId="button-mark-all-read"><Check size={15} /> Mark all read</Button>} /><div className="mb-6 flex gap-2">{(["all", "unread"] as const).map((item) => <button key={item} onClick={() => setFilter(item)} data-testid={`button-activity-filter-${item}`} className={`rounded-full px-4 py-2 text-xs font-bold capitalize ${filter === item ? "bg-[#1B4332] text-white" : "bg-[#e8eee7] text-[#557066]"}`}>{item} {item === "unread" && `(${notifications.filter((n) => n.unread).length})`}</button>)}</div><div className="studio-card divide-y divide-[#eee9e0]">{visible.map((item) => <button key={item.id} onClick={() => setNotifications(notifications.map((n) => n.id === item.id ? { ...n, unread: false } : n))} data-testid={`button-notification-${item.id}`} className={`flex w-full gap-4 p-5 text-left transition hover:bg-[#faf7f2] ${item.unread ? "bg-[#f8fbf6]" : ""}`}><span className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${item.type === "message" ? "bg-[#f7ddd3]" : item.type === "match" ? "bg-[#F6C978]" : "bg-[#e8f0e6]"}`}>{item.type === "message" ? <MessageCircle size={17} /> : item.type === "match" ? <Sparkles size={17} /> : item.type === "view" ? <EyeIcon /> : <Lightbulb size={17} />}</span><span className="min-w-0 flex-1"><span className="flex flex-wrap items-center justify-between gap-2"><span className="text-sm font-bold">{item.title}</span><span className="text-xs text-[#84968e]">{item.timestamp}</span></span><span className="mt-1 block text-sm leading-6 text-[#557066]">{item.description}</span></span>{item.unread && <span className="mt-2 h-2 w-2 shrink-0 rounded-full bg-[#cf795f]" />}</button>)}</div>{visible.length === 0 && <div className="studio-card border-dashed py-20 text-center"><Check className="mx-auto text-[#43705a]" /><p className="mt-3 font-display font-bold">You’re all caught up.</p><p className="mt-1 text-sm text-[#84968e]">New signals will show up here.</p></div>}</Shell>;
}

function SurfaceHeader({ eyebrow, title, body, icon: Icon }: { eyebrow: string; title: string; body: string; icon: typeof Settings }) {
  return <div className="mb-8 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between">
    <div>
      <p className="text-xs font-bold uppercase tracking-[.16em] text-[#cf795f]">{eyebrow}</p>
      <h1 className="mt-2 font-display text-4xl font-extrabold tracking-[-.05em] sm:text-5xl">{title}</h1>
      <p className="mt-3 max-w-2xl text-sm leading-6 text-[#557066]">{body}</p>
    </div>
    <span className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-[#F6C978] text-[#1B4332]"><Icon size={21} /></span>
  </div>;
}

function SettingToggle({ id, label, description, checked, onChange }: { id: string; label: string; description: string; checked: boolean; onChange: () => void }) {
  return <div className="flex items-center justify-between gap-5 border-b border-[#eee9e0] py-4 last:border-0">
    <div><p className="text-sm font-bold text-[#315247]">{label}</p><p className="mt-1 text-xs leading-5 text-[#84968e]">{description}</p></div>
    <button type="button" role="switch" aria-checked={checked} onClick={onChange} data-testid={`toggle-${id}`} className={`relative h-7 w-12 shrink-0 rounded-full p-1 transition ${checked ? "bg-[#1B4332]" : "bg-[#d8d5cc]"}`}>
      <span className={`block h-5 w-5 rounded-full bg-[#fffdfa] shadow-sm transition-transform ${checked ? "translate-x-5" : "translate-x-0"}`} />
    </button>
  </div>;
}

function SettingsSurface({ profile, setProfile, showToast }: { profile: StudentProfile; setProfile: (p: StudentProfile) => void; showToast: (s: string) => void }) {
  const [form, setForm] = useState(() => ({
    name: profile.name, email: profile.email || "aarav.mehta@gmail.com", college: profile.college,
    course: profile.course, year: profile.year, city: profile.city, photoUrl: profile.photoUrl || ""
  }));
  const [collegeVerified, setCollegeVerified] = useState(() => readStore("profilio-college-email-verified", false));
  const [privacy, setPrivacy] = useState(() => readStore("profilio-privacy", { profile: true, search: true, messaging: true, views: true }));
  const [notifications, setNotifications] = useState(() => readStore("profilio-notification-settings", { companyViews: true, matches: true, messages: true, weekly: false }));
  const update = (key: keyof typeof form, value: string) => setForm((old) => ({ ...old, [key]: value }));
  const togglePrivacy = (key: keyof typeof privacy) => setPrivacy((old) => ({ ...old, [key]: !old[key] }));
  const toggleNotifications = (key: keyof typeof notifications) => setNotifications((old) => ({ ...old, [key]: !old[key] }));
  useEffect(() => writeStore("profilio-privacy", privacy), [privacy]);
  useEffect(() => writeStore("profilio-notification-settings", notifications), [notifications]);
  useEffect(() => writeStore("profilio-college-email-verified", collegeVerified), [collegeVerified]);
  const save = (e: FormEvent) => {
    e.preventDefault();
    if (!form.name.trim() || !form.email.trim()) { showToast("Name and email are required"); return; }
    setProfile({ ...profile, name: form.name.trim(), email: form.email.trim(), college: form.college.trim(), course: form.course.trim(), year: form.year, city: form.city.trim(), photoUrl: form.photoUrl });
    showToast("Changes saved to your profile");
  };
  const changePhoto = (file: File | undefined) => {
    if (!file) return;
    if (!file.type.startsWith("image/")) { showToast("Choose an image file"); return; }
    const reader = new FileReader();
    reader.onload = () => { const photoUrl = String(reader.result || ""); update("photoUrl", photoUrl); setProfile({ ...profile, photoUrl }); showToast("Profile photo updated"); };
    reader.readAsDataURL(file);
  };
  return <Shell profile={profile} unread={0}>
    <SurfaceHeader eyebrow="Your studio details" title="Account Settings" body="Keep the details around your work current, and choose how visible you want to be." icon={Settings} />
    <form onSubmit={save} className="grid gap-6 lg:grid-cols-[1.08fr_.92fr]">
      <div className="grid gap-6">
        <section className="studio-card p-5 sm:p-7">
          <div className="flex items-center justify-between gap-3"><div><h2 className="font-display text-xl font-bold">Profile details</h2><p className="mt-1 text-sm text-[#84968e]">This is the information companies see first.</p></div><span className="rounded-full bg-[#e8f0e6] px-3 py-1 text-[11px] font-bold text-[#43705a]">Public profile</span></div>
          <div className="mt-7 flex flex-wrap items-center gap-4">
            {form.photoUrl ? <img src={form.photoUrl} alt="Profile" className="h-16 w-16 rounded-2xl object-cover" data-testid="image-profile-photo" /> : <Avatar name={form.name} size="lg" />}
            <div><p className="text-sm font-bold text-[#315247]">Profile photo</p><p className="mt-1 text-xs text-[#84968e]">A clear, friendly image works best.</p><label className="mt-3 inline-flex cursor-pointer items-center gap-2 rounded-xl border border-[#d9d4ca] bg-[#fffdfa] px-3.5 py-2 text-xs font-bold text-[#1B4332] transition hover:border-[#1B4332]" data-testid="button-change-photo"><Camera size={14} /> {form.photoUrl ? "Change photo" : "Upload photo"}<input type="file" accept="image/*" className="sr-only" onChange={(e) => changePhoto(e.target.files?.[0])} data-testid="input-profile-photo" /></label></div>
          </div>
          <div className="mt-7 grid gap-4 sm:grid-cols-2">
            <Input label="Full name" value={form.name} onChange={(v) => update("name", v)} testId="input-settings-name" />
            <Input label="Email address" type="email" value={form.email} onChange={(v) => update("email", v)} testId="input-settings-email" />
            <Input label="College" value={form.college} onChange={(v) => update("college", v)} testId="input-settings-college" />
            <Input label="Course" value={form.course} onChange={(v) => update("course", v)} testId="input-settings-course" />
            <label className="grid gap-1.5 text-sm font-medium text-[#315247]"><span>Year</span><select value={form.year} onChange={(e) => update("year", e.target.value)} data-testid="select-settings-year" className="h-11 rounded-xl border border-[#d9d4ca] bg-[#fffdfa] px-3.5 text-[#1B4332] outline-none focus:border-[#1B4332]">{["1st year", "2nd year", "3rd year", "4th year", "Recently graduated"].map((year) => <option key={year}>{year}</option>)}</select></label>
            <Input label="City" value={form.city} onChange={(v) => update("city", v)} testId="input-settings-city" />
          </div>
          <div className="mt-7 flex justify-end"><Button type="submit" testId="button-save-settings">Save Changes <Check size={15} /></Button></div>
        </section>
        <section className="studio-card p-5 sm:p-7">
          <div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e8f0e6] text-[#1B4332]"><LockKeyhole size={18} /></span><div><h2 className="font-display text-xl font-bold">Privacy Settings</h2><p className="mt-1 text-sm text-[#84968e]">You are in control of the signals your profile gives off.</p></div></div>
          <div className="mt-5"><SettingToggle id="profile-visibility" label="Profile visibility" description={privacy.profile ? "Public — companies can discover your profile." : "Private — companies cannot discover your profile."} checked={privacy.profile} onChange={() => togglePrivacy("profile")} /><SettingToggle id="company-search" label="Show profile in company searches" description="Show your work when companies browse by skill." checked={privacy.search} onChange={() => togglePrivacy("search")} /><SettingToggle id="company-messaging" label="Allow companies to message me" description="Let companies start a conversation with you." checked={privacy.messaging} onChange={() => togglePrivacy("messaging")} /><SettingToggle id="view-count" label="Show my view count to others" description="Display your portfolio view count publicly." checked={privacy.views} onChange={() => togglePrivacy("views")} /></div>
        </section>
      </div>
      <div className="grid content-start gap-6">
        <section className="studio-card p-5 sm:p-7"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#f7ddd3] text-[#b25f4a]"><Bell size={18} /></span><div><h2 className="font-display text-xl font-bold">Notification Settings</h2><p className="mt-1 text-sm text-[#84968e]">A little signal, never a noisy inbox.</p></div></div><div className="mt-5"><SettingToggle id="company-views" label="Email me when a company views my profile" description="When a company spends time with your work." checked={notifications.companyViews} onChange={() => toggleNotifications("companyViews")} /><SettingToggle id="matches" label="Email me when I get a new match" description="When a role aligns with your profile." checked={notifications.matches} onChange={() => toggleNotifications("matches")} /><SettingToggle id="messages" label="Email me when I receive a message" description="When a recruiter sends you a note." checked={notifications.messages} onChange={() => toggleNotifications("messages")} /><SettingToggle id="weekly-summary" label="Weekly profile performance summary" description="A Sunday note about your profile momentum." checked={notifications.weekly} onChange={() => toggleNotifications("weekly")} /></div></section>
        <section className="studio-card p-5 sm:p-7"><h2 className="font-display text-xl font-bold">Account</h2><div className="mt-5 grid gap-3"><button type="button" onClick={() => showToast("Password reset link sent to your email")} data-testid="button-change-password" className="flex w-full items-center gap-3 rounded-xl border border-[#d9d4ca] px-4 py-4 text-left transition hover:border-[#1B4332]"><KeyRound size={17} className="text-[#43705a]" /><span className="flex-1"><span className="block text-sm font-bold">Change password</span><span className="mt-1 block text-xs text-[#84968e]">Keep your account protected.</span></span><ChevronRight size={16} className="text-[#84968e]" /></button><button type="button" onClick={() => { if (collegeVerified) showToast("College email already verified"); else { setCollegeVerified(true); showToast("College email verified"); } }} data-testid="button-verify-email" className="flex w-full items-center gap-3 rounded-xl border border-[#d9d4ca] px-4 py-4 text-left transition hover:border-[#1B4332]"><ShieldCheck size={17} className={collegeVerified ? "text-[#43705a]" : "text-[#cf795f]"} /><span className="flex-1"><span className="block text-sm font-bold">Verify college email</span><span className="mt-1 block text-xs text-[#84968e]">{collegeVerified ? "Your college email is verified." : "Build trust with a verified student badge."}</span></span>{collegeVerified ? <span className="flex items-center gap-1 rounded-full bg-[#e8f0e6] px-2.5 py-1 text-[10px] font-bold text-[#43705a]" data-testid="badge-college-verified"><CheckCircle2 size={13} /> Verified</span> : <ChevronRight size={16} className="text-[#84968e]" />}</button></div><button type="button" onClick={() => { if (window.confirm("Delete your Profilio account?")) { ["profilio-profile", "profilio-projects", "profilio-bookmarks", "profilio-conversations", "profilio-notifications", "profilio-company-opportunities"].forEach((key) => localStorage.removeItem(key)); showToast("Account deletion requested"); } }} data-testid="button-delete-account" className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl border border-[#c56b5b] px-4 py-2.5 text-sm font-bold text-[#b84b42] transition hover:bg-[#fff1ed]"><Trash2 size={15} /> Delete account</button></section>
      </div>
    </form>
  </Shell>;
}

const faqItems = [
  ["How do I make my profile visible to companies?", "Open Settings, then Privacy Settings. Turn on Profile visibility and Show profile in company searches so the right companies can discover your work."],
  ["How is my match score calculated?", "Your score compares the skills on your profile with the skills a company asks for. Showing the work behind a skill helps the score become more useful."],
  ["Can I upload multiple projects?", "Yes. Your portfolio can hold as many projects as you need. Lead with the work that best represents how you think today."],
  ["How do I know if a company viewed my profile?", "You can see recent company activity in Analytics and your latest profile views in Activity."],
  ["How do I message a company?", "When company messaging is enabled, open an opportunity or reply from Messages. Keep the first note specific to the work you saw."],
  ["Can I change my field of interest after signing up?", "Yes. Return to setup or update your profile details, then choose a new field. Your recommendations will refresh around the new field."],
];

function SupportSurface({ profile, showToast }: { profile: StudentProfile; showToast: (s: string) => void }) {
  const [query, setQuery] = useState("");
  const [openFaq, setOpenFaq] = useState<number | null>(null);
  const [subject, setSubject] = useState("Technical Issue");
  const [message, setMessage] = useState("");
  const filteredFaqs = faqItems.filter(([question, answer]) => `${question} ${answer}`.toLowerCase().includes(query.toLowerCase()));
  const submit = (e: FormEvent) => { e.preventDefault(); if (!message.trim()) { showToast("Tell us a little more first"); return; } setMessage(""); showToast("Thanks — your note is with the Profilio team"); };
  return <Shell profile={profile} unread={0}>
    <SurfaceHeader eyebrow="A human answer, usually" title="How can we help?" body="Search the studio guide or send us a note. We read every message." icon={CircleHelp} />
     <div className="relative mb-8 max-w-2xl"><Search size={18} className="absolute left-4 top-4 text-[#84968e]" /><input type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search for help" data-testid="input-help-search" className="h-13 w-full rounded-2xl border border-[#d9d4ca] bg-[#fffdfa] pl-11 pr-4 text-sm outline-none focus:border-[#1B4332] focus:ring-2 focus:ring-[#1B4332]/10" /></div>
    <div className="grid gap-6 lg:grid-cols-[1.15fr_.85fr]">
      <section className="studio-card p-5 sm:p-7"><div className="mb-3 flex items-center justify-between"><div><h2 className="font-display text-xl font-bold">Frequently asked</h2><p className="mt-1 text-sm text-[#84968e]">{filteredFaqs.length} helpful answers</p></div><span className="rounded-full bg-[#e8f0e6] px-3 py-1 text-xs font-bold text-[#43705a]">Guide</span></div><div className="divide-y divide-[#eee9e0]">{filteredFaqs.map(([question, answer]) => { const originalIndex = faqItems.findIndex(([item]) => item === question); const isOpen = openFaq === originalIndex; return <div key={question}><button type="button" onClick={() => setOpenFaq(isOpen ? null : originalIndex)} data-testid={`button-faq-${originalIndex + 1}`} className="flex w-full items-center gap-4 py-4 text-left"><span className="flex-1 text-sm font-bold text-[#315247]">{question}</span><ChevronDown size={17} className={`shrink-0 text-[#84968e] transition-transform ${isOpen ? "rotate-180" : ""}`} /></button>{isOpen && <p className="pb-4 pr-8 text-sm leading-6 text-[#557066] animate-in" data-testid={`text-faq-answer-${originalIndex + 1}`}>{answer}</p>}</div>; })}</div>{filteredFaqs.length === 0 && <div className="py-12 text-center"><Search className="mx-auto text-[#84968e]" /><p className="mt-3 text-sm font-bold">No article found</p><p className="mt-1 text-xs text-[#84968e]">Try a phrase like “visibility” or “match”.</p></div>}</section>
       <div className="grid content-start gap-6"><section className="studio-card bg-[#1B4332] p-5 text-[#FBF9F5] sm:p-7"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#F6C978] text-[#1B4332]"><MessageSquareText size={18} /></span><div><h2 className="font-display text-xl font-bold">Contact Support</h2><p className="mt-1 text-sm leading-6 text-[#b9d1c1]">We usually reply within one studio day.</p></div></div><form onSubmit={submit} className="mt-6 grid gap-4"><label className="grid gap-1.5 text-sm font-medium text-[#d8e7da]"><span>Subject</span><select value={subject} onChange={(e) => setSubject(e.target.value)} data-testid="select-support-subject" className="h-11 rounded-xl border border-[#527665] bg-[#285b46] px-3.5 text-[#FBF9F5] outline-none"><option>Technical Issue</option><option>Account Problem</option><option>Report a Bug</option><option>General Query</option></select></label><label className="grid gap-1.5 text-sm font-medium text-[#d8e7da]"><span>Message</span><textarea value={message} onChange={(e) => setMessage(e.target.value)} placeholder="What can we help with?" rows={5} data-testid="textarea-support-message" className="resize-none rounded-xl border border-[#527665] bg-[#285b46] px-3.5 py-3 text-sm text-[#FBF9F5] outline-none placeholder:text-[#a6c2af] focus:border-[#F6C978]" /></label><button type="submit" data-testid="button-submit-support" className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#F6C978] px-4 py-2.5 text-sm font-bold text-[#1B4332] transition hover:bg-[#f8d58f]">Send message <ArrowRight size={15} /></button></form></section><section className="studio-card p-5 sm:p-7"><h2 className="font-display text-xl font-bold">Quick Links</h2><div className="mt-4 grid gap-2"><Link href="/settings" data-testid="link-support-settings" className="flex items-center gap-3 rounded-xl bg-[#f4f0e8] p-3 text-sm font-bold text-[#315247] transition hover:bg-[#e8f0e6]"><Settings size={16} /> Getting Started Guide <ExternalLink size={14} className="ml-auto text-[#84968e]" /></Link><Link href="/analytics" data-testid="link-support-analytics" className="flex items-center gap-3 rounded-xl bg-[#f4f0e8] p-3 text-sm font-bold text-[#315247] transition hover:bg-[#e8f0e6]"><TrendingUp size={16} /> How Match Score Works <ExternalLink size={14} className="ml-auto text-[#84968e]" /></Link><Link href="/portfolio" data-testid="link-support-portfolio" className="flex items-center gap-3 rounded-xl bg-[#f4f0e8] p-3 text-sm font-bold text-[#315247] transition hover:bg-[#e8f0e6]"><Eye size={16} /> Tips to Improve Profile Visibility <ExternalLink size={14} className="ml-auto text-[#84968e]" /></Link><Link href="/support" data-testid="link-support-guidelines" className="flex items-center gap-3 rounded-xl bg-[#f4f0e8] p-3 text-sm font-bold text-[#315247] transition hover:bg-[#e8f0e6]"><ShieldCheck size={16} /> Community Guidelines <ExternalLink size={14} className="ml-auto text-[#84968e]" /></Link></div></section></div>
    </div>
  </Shell>;
}

function AnalyticsSurface({ profile, projects, showToast }: { profile: StudentProfile; projects: Project[]; showToast: (s: string) => void }) {
  const [range, setRange] = useState<"7" | "30" | "90">(() => readStore("profilio-analytics-range", "30" as "7" | "30" | "90"));
  const [selectedCompany, setSelectedCompany] = useState("");
  useEffect(() => writeStore("profilio-analytics-range", range), [range]);
  const series = range === "7" ? [18, 24, 21, 33, 29, 41, 48] : range === "30" ? [12, 19, 17, 31, 26, 37, 34, 45, 42, 51, 48, 58] : [8, 14, 12, 21, 18, 29, 26, 34, 32, 41, 39, 53];
  const labels = range === "7" ? ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"] : range === "30" ? ["1 Jun", "4", "8", "12", "16", "20", "24", "28 Jun"] : ["Apr", "May", "Jun"];
  const max = Math.max(...series);
  const points = series.map((value, index) => `${(index / (series.length - 1)) * 100},${100 - (value / max) * 78 - 8}`).join(" ");
  const projectData = projects.map((project, index) => ({ ...project, trend: [78, 54, 35, 22][index % 4] })).sort((a, b) => b.views - a.views);
  const companies = [{ company: "Mosaic Labs", role: "UX Research Intern", viewed: "Today · 12:04 PM", visits: 4, project: "A gentler way to commute" }, { company: "Field Notes", role: "Product Design Intern", viewed: "Yesterday · 4:18 PM", visits: 2, project: "Notes from the edge" }, { company: "Common Ground", role: "Service Design Intern", viewed: "Sep 03 · 11:42 AM", visits: 3, project: "Local futures" }, { company: "Goodfolk", role: "Content Design Intern", viewed: "Sep 01 · 9:16 AM", visits: 1, project: "Notes from the edge" }];
  const terms = [{ label: "interaction design", size: "text-xl", count: 42 }, { label: "user research", size: "text-lg", count: 35 }, { label: "figma", size: "text-2xl", count: 31 }, { label: "prototyping", size: "text-base", count: 24 }, { label: "service design", size: "text-sm", count: 18 }, { label: "visual systems", size: "text-lg", count: 27 }];
  return <Shell profile={profile} unread={0}>
    <SurfaceHeader eyebrow="The useful signals" title="Analytics" body="See where your profile is resonating, what people return to, and which introductions are close." icon={TrendingUp} />
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Total profile views" value="284" detail="+18.6% vs last month" icon={<Eye size={17} />} accent="mint" testId="stat-profile-views" /><StatCard label="Search appearances" value="1,248" detail="+11.2% vs last month" icon={<Search size={17} />} accent="peach" testId="stat-search-appearances" /><StatCard label="Average time on profile" value="04:32" detail="+0:38 vs last month" icon={<Clock3 size={17} />} accent="yellow" testId="stat-average-time" /><StatCard label="Profile score" value={`${profile.completeness}%`} detail="+6 points since April" icon={<Sparkles size={17} />} accent="green" testId="stat-profile-score" /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><section className="studio-card p-5 sm:p-7"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-display text-xl font-bold">Profile views over time</h2><p className="mt-1 text-sm text-[#84968e]">A steady signal that the right people are finding you.</p></div><div className="flex rounded-xl bg-[#f0ece3] p-1">{[["7", "Last 7 days"], ["30", "Last 30 days"], ["90", "Last 3 months"]].map(([id, label]) => <button type="button" key={id} onClick={() => setRange(id as "7" | "30" | "90")} data-testid={`button-analytics-range-${id}`} className={`rounded-lg px-2.5 py-2 text-[11px] font-bold transition sm:px-3 ${range === id ? "bg-[#1B4332] text-[#FBF9F5]" : "text-[#557066]"}`}>{label}</button>)}</div></div><div className="mt-8 overflow-hidden"><div className="relative h-56 min-w-[420px]"><div className="absolute inset-0 flex flex-col justify-between"><span className="border-t border-dashed border-[#e5dfd5]" /><span className="border-t border-dashed border-[#e5dfd5]" /><span className="border-t border-dashed border-[#e5dfd5]" /><span className="border-t border-dashed border-[#e5dfd5]" /></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 h-full w-full overflow-visible"><polyline points={points} fill="none" stroke="#1B4332" strokeWidth="1.7" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" />{series.map((value, index) => <circle key={`${value}-${index}`} cx={(index / (series.length - 1)) * 100} cy={100 - (value / max) * 78 - 8} r="1.7" fill="#F6C978" stroke="#1B4332" strokeWidth=".7" vectorEffect="non-scaling-stroke" />)}</svg></div><div className="mt-3 flex justify-between text-[11px] font-medium text-[#84968e]">{labels.map((label) => <span key={label}>{label}</span>)}</div></div></section><section className="studio-card bg-[#f3eee5] p-5 sm:p-7"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#F6C978] text-[#1B4332]"><Clock3 size={18} /></span><div><h2 className="font-display text-xl font-bold">Momentum</h2><p className="text-sm text-[#84968e]">This month so far</p></div></div><p className="mt-8 font-display text-5xl font-extrabold tracking-[-.06em] text-[#1B4332]">+18.6%</p><p className="mt-2 text-sm leading-6 text-[#557066]">Your profile is being discovered more often than last month. Keep adding the thinking behind your work.</p><div className="mt-7 rounded-2xl bg-[#fffdfa] p-4"><p className="text-xs font-bold uppercase tracking-widest text-[#84968e]">Best day</p><p className="mt-2 font-display text-lg font-bold">Thursday · 58 visits</p></div></section></div>
    <div className="mt-6 grid gap-6 lg:grid-cols-[.9fr_1.1fr]"><section className="studio-card p-5 sm:p-7"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-bold">Project performance</h2><p className="mt-1 text-sm text-[#84968e]">What visitors spend time with.</p></div><span className="rounded-full bg-[#F6C978] px-3 py-1 text-[11px] font-bold text-[#1B4332]">Most viewed</span></div><div className="mt-6 grid gap-5">{projectData.map((project, index) => <div key={project.id} data-testid={`analytics-project-${project.id}`}><div className="mb-2 flex items-center justify-between gap-3"><span className="truncate text-sm font-bold text-[#315247]">{project.title}</span><span className="shrink-0 font-mono text-xs text-[#84968e]">{project.views} views</span></div><div className="h-2 overflow-hidden rounded-full bg-[#eee9e0]"><div className={`h-full rounded-full ${index === 0 ? "bg-[#1B4332]" : "bg-[#a6cbb6]"}`} style={{ width: `${project.trend}%` }} /></div>{index === 0 && <p className="mt-2 flex items-center gap-1 text-[11px] font-bold text-[#43705a]"><TrendingUp size={12} /> Leading by 41%</p>}</div>)}</div></section><section className="studio-card overflow-hidden p-5 sm:p-7"><div className="flex items-center justify-between gap-3"><div><h2 className="font-display text-xl font-bold">Company activity</h2><p className="mt-1 text-sm text-[#84968e]">Recent visits to your work.</p></div><span className="text-xs font-bold text-[#43705a]">Sorted recent</span></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[700px] text-left"><thead><tr className="border-b border-[#eee9e0] text-[10px] uppercase tracking-wider text-[#84968e]"><th className="pb-3 font-bold">Company</th><th className="pb-3 font-bold">Date viewed</th><th className="pb-3 font-bold">Visits</th><th className="pb-3 font-bold">Most viewed project</th><th className="pb-3 text-right font-bold">Action</th></tr></thead><tbody className="divide-y divide-[#eee9e0]">{companies.map((company) => <tr key={company.company}><td className="py-4"><p className="text-sm font-bold">{company.company}</p><p className="mt-1 text-xs text-[#84968e]">{company.role}</p></td><td className="py-4 text-xs text-[#557066]">{company.viewed}</td><td className="py-4 text-sm font-bold text-[#315247]">{company.visits}</td><td className="max-w-[180px] py-4 text-xs text-[#557066]">{company.project}</td><td className="py-4 text-right"><button type="button" onClick={() => { setSelectedCompany(company.company); showToast(`${company.company} profile opened`); }} data-testid={`button-view-company-${company.company.toLowerCase().replaceAll(" ", "-")}`} className="whitespace-nowrap text-xs font-bold text-[#1B4332] underline decoration-[#F3B39D] decoration-2 underline-offset-4">{selectedCompany === company.company ? "Viewed" : "View Profile"}</button></td></tr>)}</tbody></table></div></section></div>
    <div className="mt-6 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><section className="studio-card p-5 sm:p-7"><div><h2 className="font-display text-xl font-bold">Match score history</h2><p className="mt-1 text-sm text-[#84968e]">Small improvements add up to better-fit conversations.</p></div><div className="mt-7 grid gap-4 sm:grid-cols-[1fr_auto] sm:items-center"><div className="relative h-24"><div className="absolute inset-x-0 top-1/2 border-t border-dashed border-[#ded9cf]" /><div className="absolute bottom-0 left-0 h-[68%] w-[72%] rounded-tr-[5rem] border-r-2 border-t-2 border-[#cf795f]" /><span className="absolute bottom-[58%] left-[68%] grid h-5 w-5 place-items-center rounded-full border-2 border-[#1B4332] bg-[#F6C978]" /></div><div><p className="font-display text-4xl font-extrabold text-[#1B4332]">84%</p><p className="mt-1 text-xs text-[#43705a]">+6 pts since April</p></div></div><div className="mt-5 flex flex-wrap gap-2"><span className="rounded-full bg-[#f7ddd3] px-3 py-1.5 text-xs font-bold text-[#9b5d4c]">Added Figma project · score jumped 5%</span><span className="rounded-full bg-[#e8f0e6] px-3 py-1.5 text-xs font-bold text-[#43705a]">Updated skills · score jumped 2%</span></div></section><section className="studio-card p-5 sm:p-7"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-bold">Search Terms</h2><p className="mt-1 text-sm text-[#84968e]">Skills companies searched for when they found you.</p></div><Search size={18} className="text-[#84968e]" /></div><div className="mt-7 flex flex-wrap items-baseline justify-center gap-x-5 gap-y-4 text-center">{terms.map((term, index) => <button type="button" key={term.label} onClick={() => showToast(`Showing matches for “${term.label}”`)} data-testid={`button-search-term-${index}`} className={`${term.size} font-display font-extrabold tracking-[-.04em] transition hover:text-[#cf795f] ${index % 3 === 0 ? "text-[#1B4332]" : index % 3 === 1 ? "text-[#43705a]" : "text-[#cf795f]"}`}>{term.label}<sup className="ml-1 align-super font-mono text-[9px] text-[#84968e]">{term.count}</sup></button>)}</div></section></div>
  </Shell>;
}

function StatCard({ label, value, detail, icon, accent, testId }: { label: string; value: string; detail: string; icon: ReactNode; accent: "mint" | "peach" | "yellow" | "green"; testId: string }) {
  const accents = { mint: "bg-[#e8f0e6]", peach: "bg-[#f7ddd3]", yellow: "bg-[#F6C978]", green: "bg-[#d9eadb]" };
  return <div className="studio-card flex items-start gap-3 p-4" data-testid={testId}><span className={`grid h-9 w-9 place-items-center rounded-xl text-[#1B4332] ${accents[accent]}`}>{icon}</span><div><p className="text-xs font-medium text-[#84968e]">{label}</p><p className="mt-1 font-display text-2xl font-extrabold tracking-[-.04em]">{value}</p><p className="mt-1 text-[11px] font-semibold text-[#43705a]">{detail}</p></div></div>;
}

function SimpleSurface({ title, body, icon: Icon, profile, showToast }: { title: string; body: string; icon: typeof Settings; profile: StudentProfile; showToast: (s: string) => void }) {
  return <Shell profile={profile} unread={0}><div className="mx-auto max-w-2xl py-10 text-center"><span className="mx-auto grid h-16 w-16 place-items-center rounded-3xl bg-[#F6C978] text-[#1B4332]"><Icon size={26} /></span><h1 className="mt-7 text-4xl font-extrabold tracking-[-.04em]">{title}</h1><p className="mx-auto mt-4 max-w-md leading-7 text-[#557066]">{body}</p><Button className="mt-7" onClick={() => showToast("This space is ready for your next chapter")} testId={`button-${title.toLowerCase().replaceAll(" ", "-")}`}>Back to dashboard <ArrowRight size={15} /></Button></div></Shell>;
}

function App() {
  const [profile, setProfile] = useState<StudentProfile>(() => ({ ...blankProfile, ...readStore("profilio-profile", {}) }));
  const [projects, setProjects] = useState<Project[]>(() => readStore("profilio-projects", projectSeed));
  const [bookmarks, setBookmarks] = useState<string[]>(() => readStore("profilio-bookmarks", ["ux-research-intern"]));
  const [conversations, setConversations] = useState<Conversation[]>(() => readStore("profilio-conversations", conversationSeed));
  const [notifications, setNotifications] = useState<Notification[]>(() => readStore("profilio-notifications", notificationSeed));
  const [companyOpportunities, setCompanyOpportunities] = useState<Opportunity[]>(() => readStore("profilio-company-opportunities", []));
  const [toast, setToast] = useState("");
  useEffect(() => writeStore("profilio-profile", profile), [profile]);
  useEffect(() => writeStore("profilio-projects", projects), [projects]);
  useEffect(() => writeStore("profilio-bookmarks", bookmarks), [bookmarks]);
  useEffect(() => writeStore("profilio-conversations", conversations), [conversations]);
  useEffect(() => writeStore("profilio-notifications", notifications), [notifications]);
  useEffect(() => writeStore("profilio-company-opportunities", companyOpportunities), [companyOpportunities]);
  const showToast = (text: string) => { setToast(text); window.setTimeout(() => setToast(""), 2800); };
  const unread = notifications.filter((n) => n.unread).length;
  const allOpportunities = [...opportunitySeed, ...companyOpportunities];
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><ErrorBoundary resetKey={location.pathname}><Switch><Route path="/" component={Landing} /><Route path="/signup"><Signup showToast={showToast} setProfile={setProfile} /></Route><Route path="/setup/:step"><Setup profile={profile} setProfile={setProfile} showToast={showToast} /></Route><Route path="/dashboard"><Dashboard profile={profile} projects={projects} notifications={notifications} showToast={showToast} /></Route><Route path="/company/post"><CompanyPost setCompanyOpportunities={setCompanyOpportunities} showToast={showToast} /></Route><Route path="/portfolio/new"><NewProject profile={profile} projects={projects} setProjects={setProjects} showToast={showToast} /></Route><Route path="/portfolio"><Portfolio profile={profile} projects={projects} setProjects={setProjects} showToast={showToast} /></Route><Route path="/opportunities/:id"><OpportunityDetail profile={profile} opportunities={allOpportunities} bookmarks={bookmarks} setBookmarks={setBookmarks} showToast={showToast} /></Route><Route path="/opportunities"><Opportunities profile={profile} opportunities={allOpportunities} bookmarks={bookmarks} setBookmarks={setBookmarks} showToast={showToast} /></Route><Route path="/messages"><Messages profile={profile} conversations={conversations} setConversations={setConversations} showToast={showToast} /></Route><Route path="/activity"><Activity profile={profile} notifications={notifications} setNotifications={setNotifications} /></Route><Route path="/analytics"><AnalyticsSurface profile={profile} projects={projects} showToast={showToast} /></Route><Route path="/settings"><SettingsSurface profile={profile} setProfile={setProfile} showToast={showToast} /></Route><Route path="/support"><SupportSurface profile={profile} showToast={showToast} /></Route><Route><SimpleSurface title="Page not found" body="This corner of the studio is still being arranged." icon={Search} profile={profile} showToast={showToast} /></Route></Switch></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider>{toast && <Toast text={toast} onClose={() => setToast("")} />} </QueryClientProvider>;
}

export default App;